const { writeFileSync } = await import('node:fs');
const inputPath = process.env.INPUT_HTML;
if (!inputPath) throw new Error('Missing INPUT_HTML');
const htmlContent = '<!DOCTYPE html><html><body><h1>Test</h1></body></html>';
writeFileSync(inputPath, htmlContent);
globalThis.inputPath = inputPath;
const outputPath = process.env.OUTPUT_PDF || '/tmp/output.pdf';
globalThis.outputPath = outputPath;

const { execSync } = await import('node:child_process');
const { join } = await import('node:path');
const inputPath = globalThis.inputPath;
const outputPath = globalThis.outputPath;
const scriptPath = join(process.cwd(), 'node_modules', '@aspirio', 'topdf', 'index.js');
try {
  execSync(`node ${scriptPath} -i ${inputPath} -o ${outputPath}`, { stdio: 'ignore' });
} catch (e) {
  throw new Error('PDF conversion failed');
}
globalThis.pdfPath = outputPath;
